"""Render the per-PR Kustomize overlay.

Phase 2 ships the shared ``k8s/base``; this module generates the overlay
directory for one pull request — a ``kustomization.yaml`` that points at the
base, sets the namespace, pins the image tag, and patches the ingress host —
plus a ``namespace.yaml`` so ``kubectl apply -k`` creates the namespace itself
(carrying the ``preview.env/*`` labels that teardown and cleanup select on).
"""

NAMESPACE_FILE = "namespace.yaml"

NAMESPACE_TEMPLATE = """\
# Generated by previewctl — do not edit by hand.
apiVersion: v1
kind: Namespace
metadata:
  name: {namespace}
"""

KUSTOMIZATION_TEMPLATE = """\
# Generated by previewctl — do not edit by hand.
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization

namespace: {namespace}

resources:
  - {base}
  - namespace.yaml

images:
  - name: {image}{new_name}
    newTag: {tag}

labels:
  - pairs:
      preview.env/platform: "true"
      preview.env/pr: "{pr}"
    includeSelectors: true

patches:
  - target:
      kind: Ingress
    patch: |-
      - op: replace
        path: /spec/rules/0/host
        value: {host}
"""


def render_kustomization(
    *,
    namespace: str,
    base: str,
    image: str,
    tag: str,
    pr: int,
    host: str,
    new_name: str | None = None,
) -> str:
    """Return the contents of the overlay ``kustomization.yaml``.

    ``image`` is the image name as written in the base; ``new_name``
    optionally replaces it (e.g. with the registry path the PR image was
    pushed to), since kustomize only retags images whose name matches.
    """
    for field, value in {
        "namespace": namespace,
        "image": image,
        "tag": tag,
        "host": host,
    }.items():
        if not value or not value.strip():
            raise ValueError(f"{field} must be non-empty")
    if pr < 1:
        raise ValueError("pr must be a positive integer")
    if new_name is not None and not new_name.strip():
        raise ValueError("new_name must be non-empty when given")
    return KUSTOMIZATION_TEMPLATE.format(
        namespace=namespace,
        base=base,
        image=image,
        new_name=f"\n    newName: {new_name}" if new_name else "",
        tag=tag,
        pr=pr,
        host=host,
    )


def preview_host(pr: int, domain: str) -> str:
    """Return the ingress host for a PR, e.g. ``pr-12.preview.example.com``."""
    if pr < 1:
        raise ValueError("pr must be a positive integer")
    domain = domain.strip().strip(".")
    if not domain:
        raise ValueError("domain must be non-empty")
    return f"pr-{pr}.{domain}"


def render_namespace(namespace: str) -> str:
    """Return the ``namespace.yaml`` the overlay lists as a resource."""
    if not namespace or not namespace.strip():
        raise ValueError("namespace must be non-empty")
    return NAMESPACE_TEMPLATE.format(namespace=namespace)


def write_overlay(directory, content: str, namespace: str) -> None:
    """Write ``<directory>/kustomization.yaml`` and its ``namespace.yaml``."""
    from pathlib import Path

    path = Path(directory)
    path.mkdir(parents=True, exist_ok=True)
    (path / "kustomization.yaml").write_text(content, encoding="utf-8")
    (path / NAMESPACE_FILE).write_text(render_namespace(namespace), encoding="utf-8")
